public class Main {
    static int hitungTotal(int harga, int jumlah) {
        return harga * jumlah;
    }

    static int hitungTotal(int harga) {
        return harga;
    }


    static int hitungTotal(int harga, int jumlah, int diskon) {
        return harga * jumlah - diskon;
    }

    public static void main(String[] args) {
        System.out.println(hitungTotal(5000, 2));
        System.out.println(hitungTotal(7000));
        System.out.println("Pakai diskon: " + hitungTotal(5000, 2, 2000));
    }
}

